@Test public void cp1252SubstitutionTable() {
    for_1_oe (int i = 0; i < Tokeniser.win1252Extensions.length; i++) {
        String s = new String(new byte[]{ (byte) (i + Tokeniser.win1252ExtensionsStart) }, Charset.forName("Windows-1252"));
        assertEquals(1, s.length());
    }
    }

@Test public void cp1252SubstitutionTable() {
    for_2_oe (int i = 0; i < Tokeniser.win1252Extensions.length; i++) {
        String s = new String(new byte[]{ (byte) (i + Tokeniser.win1252ExtensionsStart) }, Charset.forName("Windows-1252"));
        // removed other assertion

        // some of these characters are illegal
        if (s.charAt(0) == '\ufffd') { continue; }

        assertEquals(s.charAt(0), Tokeniser.win1252Extensions[i], "At: " + i);
    }
    }

@Test
public void bailsIfRemovingProtocolThatsNotSet_1_oe() {
    assertThrows(IllegalArgumentException.class, () -> { // a case that came up on the email list Safelist w = Safelist.none(); // note no add tag, and removing protocol without adding first w.addAttributes("a", "href"); w.removeProtocols("a", "href", "javascript"); // with no protocols enforced, this was a noop. Now validates. });
}
}

